(window.MUSEUM_PAINT_T = window.MUSEUM_PAINT_T || {})["id"] = {"ui":{"lead":"Orang tidak hanya memainkan permainan, tetapi juga melukisnya. Perbesar lukisan dan patung dari 3.300 tahun ini dan lihat detailnya.","details":"Detail","links":"Lihat atau mainkan permainannya","record":"Tentang karya","game":"Permainan","exhibit":"Koleksi","room":"Ruang","room_chance":"Peluang","hint":"Cubit atau gulir untuk memperbesar · seret untuk menggeser · ketuk nomor","r_artist":"Seniman","r_date":"Masa","r_place":"Tempat","r_medium":"Bahan dan teknik","r_size":"Ukuran","r_museum":"Museum","r_credit":"Asal perolehan","r_rights":"Gambar","met":"The Metropolitan Museum of Art","cc0":"Akses terbuka (domain publik)","metlink":"Karya ini di situs museum","credit":"Gambar: The Metropolitan Museum of Art, The Cleveland Museum of Art, The Art Institute of Chicago, dan Rijksmuseum, akses terbuka (domain publik).","cma":"The Cleveland Museum of Art","aic":"The Art Institute of Chicago","rijks":"Rijksmuseum, Amsterdam"},"nefertari":{"title":"Ratu Nefertari Bermain Senet","artist":"Nina de Garis Davies (salinan)","date":"asli sekitar 1290–1224 SM · salinan 1921–22","place":"Mesir (Lembah Para Ratu)","game":"Senet","medium":"Tempera di atas kertas (salinan setengah ukuran)","p":["Nefertari adalah permaisuri utama Ramses II. Ini salinan lukisan dari makamnya di Lembah Para Ratu, dibuat di dalam makam itu pada 1921–22; bahkan retakan dan bagian dinding yang hilang ikut disalin.","Sang ratu duduk di depan papan dan bermain senet melawan lawan yang tak terlihat. Dilukis di makam, permainan ini diduga bermakna lebih dari hiburan: memenangkan perjalanan ke alam baka."],"spots":[["Dua jenis bidak","Di papan ada bidak berujung runcing dan bidak berbentuk gulungan benang: satu set untuk tiap pemain."],["Tangan sang ratu","Jarinya hendak mengambil bidak."],["Papan dan penyangga","Papan digambar dari samping, jadi petaknya tidak terlihat. Papan diletakkan di penyangga berkaki ramping."],["Namanya","Nama sang ratu tertulis di dalam bingkai oval, kartus."],["Lawan yang tak terlihat","Tak ada siapa pun di seberangnya: sang ratu bermain melawan lawan yang tak tampak."]]},"hydria":{"title":"Akhilleus dan Aias Bermain Permainan Papan (guci air)","artist":"Dikaitkan dengan Kelompok Leagros","date":"sekitar 510 SM","place":"Yunani (Attika)","game":"Permainan dadu","medium":"Terakota (figur hitam)","p":["Saat pengepungan Troya, dua pahlawan Yunani, Akhilleus dan Aias, mengisi waktu di depan papan. Adegan ini diciptakan sekitar 540 SM oleh pembuat tembikar dan pelukis Eksekias; aslinya tersimpan pada amfora di Museum Vatikan.","Tema ini sangat digemari antara sekitar 540 dan 480 SM, dan lebih dari 150 contoh diketahui. Pada guci ini, dewi Athena berdiri di tengah. Kedua pahlawan memainkan permainan yang bidaknya maju menurut lemparan dadu."],"spots":[["Athena","Dewi Athena berdiri di antara keduanya."],["Pahlawan di kiri","Masih memegang tombak, ia membungkuk ke papan."],["Pahlawan di kanan","Ia juga tak meletakkan senjatanya: sejenak bermain di tengah perang."],["Papan","Balok rendah di antara mereka adalah papannya."],["Bahu guci","Di bahu guci, sebuah kereta perang berangkat."]]},"liubo":{"title":"Sepasang Figur Duduk Bermain Liubo","date":"abad ke-1 SM – abad ke-1 M","place":"Tiongkok (dinasti Han)","game":"Liubo","medium":"Gerabah berwarna","p":["Dua pemain liubo, permainan yang sangat digemari di Tiongkok zaman Han. Figur seperti ini diletakkan di makam dengan harapan kesenangan hidup terus berlanjut setelah kematian.","Di foto, papan liubo dan bidak tulang dari koleksi museum ini diletakkan di antara mereka. Figur ini menangkap saat dramatis dalam permainan yang memanas."],"spots":[["Papan liubo","Papan yang sama dengan “Papan dan Bidak Liubo” di koleksi: lihat tanda T, L, dan V."],["Pemain di kiri","Ia mengamati papan dengan tenang."],["Pemain di kanan","Tangan terangkat, mulut terbuka lebar: apakah ia baru membuat langkah kemenangan?"],["Bidak di papan","Bidak tulang berdiri di kedua ujung papan."],["Bidak di luar papan","Ada pula bidak di lantai."]]},"shahnama":{"title":"“Buzurjmihr Memecahkan Permainan Catur dari India”, dari Shahnama Shah Tahmasp","artist":"Lukisan dikaitkan dengan ʿAbd al-Vahhab","date":"sekitar 1530–35","place":"Iran (Tabriz)","game":"Catur","medium":"Cat air opak, tinta, perak, dan emas di atas kertas","p":["Adegan dari epos Ferdowsi, Shahnama (Kitab Para Raja). Raja India mengirim utusan membawa papan dan bidak catur dan menantang raja Persia Nushirvan: jika ia bisa menemukan cara memainkannya, India akan membayar upeti.","Hanya bijak muda Buzurjmihr yang memecahkannya tepat waktu. Dalam Shahnama, Persia lalu mengirim backgammon sebagai balasan, dan orang India tak mampu memecahkannya. Raja dan para bangsawan menatap lekat papan dan para pemain."],"spots":[["Papan catur","Bidak berdiri di papan berkotak-kotak, begitu kecil hingga bentuknya sulit dikenali."],["Raja Nushirvan","Di singgasananya, ia menunggu teka-teki terpecahkan."],["Di sekeliling papan","Para pemain membungkuk ke papan."],["Bait-bait syair","Bingkai atas dan bawah memuat syair Ferdowsi."],["Para bangsawan","Orang-orang bersorban dengan tongkat merah tinggi menonton sambil berdiri."]]},"chaupar":{"title":"Siwa dan Parwati Bermain Chaupar, dari seri Rasamanjari","artist":"Devidasa dari Nurpur","date":"1694–95","place":"India (Basohli, Jammu)","game":"Chaupar (kerabat leluhur Ludo)","medium":"Cat air opak, tinta, perak, dan emas di atas kertas","p":["Satu halaman dari seri yang menggambarkan Rasamanjari, puisi cinta Sanskerta abad ke-15. Dewa Siwa dan istrinya Parwati duduk di atas kulit harimau mengelilingi papan berbentuk salib.","Siwa baru saja mengambil kalung Parwati dengan curang, dan Parwati memohon kepadanya. Warna berani, kedalaman ruang yang samar, serta warna dan gerak tubuh yang bermakna: itulah ciri aliran Basohli."],"spots":[["Papan berbentuk salib","Chaupar dan pachisi dimainkan di papan berbentuk salib seperti ini."],["Batang putih di papan","Kemungkinan dadu panjang (pasa) untuk chaupar."],["Siwa","Bertubuh putih, dengan ular di leher."],["Parwati","Dengan tangan terulur, ia meminta kalungnya kembali."],["Kulit harimau","Keduanya duduk di atas kulit harimau."]]},"shogi":{"title":"Wanita dan Pria Muda Bermain Shōgi (“Chūnagon Kanesuke”, dari Tiga Puluh Enam Penyair Abadi)","artist":"Suzuki Harunobu","date":"sekitar 1767–69","place":"Jepang (Edo)","game":"Shogi","medium":"Cetak cukil kayu (nishiki-e)","p":["Cetakan dari seri yang mengacu pada Tiga Puluh Enam Penyair Abadi; yang ini mewakili penyair Chūnagon Kanesuke. Pada malam musim panas, di samping kelambu, seorang wanita dan pria muda bermain shogi.","Harunobu adalah seniman yang mempopulerkan cetakan berwarna penuh, dicetak dengan banyak papan. Bahkan bidak di papan digambar dengan rinci."],"spots":[["Papan shogi berkaki","Papan tebal berkaki, seperti sekarang."],["Kotak kecil","Kemungkinan kotak tempat bidak."],["Kelambu","Kelambu hijau tergantung: ini malam musim panas."],["Lentera","Lampu berdiri menerangi papan."],["Puisi","Bingkai berbentuk awan memuat nama penyair dan sebuah puisi."]]},"sugoroku":{"title":"Dua Wanita Muda Bermain Sugoroku","artist":"Utagawa Toyokuni I","date":"zaman Edo (akhir abad ke-18 – awal abad ke-19)","place":"Jepang (Edo)","game":"Ban-sugoroku (kerabat backgammon)","medium":"Diptik cetak cukil kayu","p":["Dua cetakan disatukan menjadi gambar lebar: para wanita muda di sebuah ruangan menikmati permainan ban-sugoroku. Permainan ini kerabat backgammon, satu garis dengan papan sugoroku Shōsōin di koleksi ini.","Di papan ada batu putih dan hitam, dan wanita muda di kanan memegang wadah untuk mengocok dadu. Gunung Fuji terlihat dari jendela."],"spots":[["Papan","Batu putih dan hitam di petak-petaknya yang panjang."],["Wadah dadu","Dadu dikocok di dalamnya."],["Batu di luar papan","Sudah dikeluarkan, atau belum masuk?"],["Gunung Fuji","Fuji di balik jendela."],["Sambungan","Di sini dua cetakan bertemu."]]},"eakins":{"title":"Para Pemain Catur","artist":"Thomas Eakins","date":"1876","place":"Amerika Serikat (Philadelphia)","game":"Catur","medium":"Cat minyak di atas kayu","p":["Di ruang tamu sebuah rumah di Philadelphia, dua sahabat bermain catur sementara ayah sang seniman, Benjamin Eakins, menonton. Eakins belajar menyusun ruang dengan cermat dan detail yang tepat dari gurunya di Paris, Gérôme.","Pada 1881, Para Pemain Catur menjadi karya pertama yang diterima Metropolitan Museum sebagai hadiah dari seniman yang masih hidup."],"spots":[["Bidak catur","Di ruangan yang remang, bidak di papan tampak terang tersinari."],["Ayah sang seniman","Berdiri menyaksikan permainan: Benjamin Eakins."],["Pemain di kanan","Pelukis George W. Holmes, sahabat ayah sang seniman."],["Laci meja","Tulisan Latin: “Putra Benjamin Eakins melukis ini pada ’76.”"],["Di atas perapian","Reproduksi lukisan Gérôme, guru Eakins."],["Kucing","Di lantai, hanya kucing yang tampak tak peduli pada permainan."]]},"weiqi":{"title":"Pemandangan dengan Dewa Tao Bermain Weiqi","artist":"Diatribusikan kepada Dai Jin","date":"Dinasti Ming, abad ke-15–16","place":"Tiongkok","game":"Weiqi (go)","medium":"Gulungan gantung; tinta dan warna di atas sutra","size":"175,2 × 106,7 cm","credit":"","p":["Gulungan gantung besar yang diatribusikan kepada pelukis Ming Dai Jin (sekitar 1388–1462). Berasal dari Zhejiang dan dikenal dengan lanskapnya yang kuat, ia kemudian dianggap pendiri aliran Zhe. Di bawah tebing menjulang dan pohon besar, manusia dilukis kecil.","Di tanah yang teduh, dua dewa duduk berhadapan di depan papan weiqi bergaris, dengan piring buah dan guci di samping. Sosok yang berjongkok di kiri mengingatkan pada penebang kayu yang menonton para dewa bermain di gunung sampai gagang kapaknya lapuk (legenda Lanke), meski judul museum hanya menyebut dewa Tao bermain weiqi."],"spots":[["Papan","Papan berbingkai dengan kisi halus."],["Dewa berjanggut","Dewa berjanggut panjang, duduk santai."],["Dewa bertopi biru","Condong ke papan; di dekat lututnya ada mangkuk batu."],["Sosok berjongkok","Mengintip papan dari kiri; mungkin si penebang kayu dalam legenda."],["Buah dan guci","Piring dan guci di seberang papan."],["Tanda tangan dan cap","Tanda tangan dan dua cap merah di kanan atas."]]},"webb":{"title":"Pemain backgammon (lemari)","artist":"Philip Webb (desain), Edward Burne-Jones (lukisan), Morris, Marshall, Faulkner & Co. (pembuat)","date":"1861","place":"Inggris (London)","game":"Backgammon","medium":"Kayu pinus dicat, cat minyak di atas kulit, kuningan, tembaga","size":"T. 185,4; L. 114,3; D. 53,3 cm","credit":"Rogers Fund, 1926","p":["Salah satu perabot paling awal dari perusahaan yang didirikan William Morris bersama teman-temannya pada 1861. Di kulit pintunya dilukis dengan cat minyak seorang pria dan wanita berbusana abad pertengahan yang sedang bermain backgammon. Lemari ini dipamerkan di Pameran Internasional London 1862.","Karya ini merangkum cita-cita gerakan Arts and Crafts untuk menghapus batas antara seni rupa dan seni terapan. Latar kulitnya ditatah titik-titik kecil, teknik abad pertengahan."],"spots":[["Papan","Papan backgammon di meja di antara keduanya."],["Pria","Seorang pemuda memegang bidak, menatap papan."],["Wanita","Di hadapannya, seorang wanita memegang bidak (atau wadah dadu)."],["Bunga di kaki mereka","Bunga tumbuh di kaki para pemain."],["Kulit bertatah","Latar kulit ditatah titik-titik halus yang menangkap cahaya."],["Pita belah ketupat","Pita bermotif belah ketupat di atas emas membingkai pintu di atas dan bawah."]]},"liberale":{"title":"Para Pemain Catur","artist":"Liberale da Verona","date":"sekitar 1475","place":"Italia (Verona)","game":"Catur","medium":"Tempera di atas kayu","size":"34,9 × 41,3 cm","credit":"Koleksi Maitland F. Griggs, wasiat Maitland F. Griggs, 1943","p":["Pecahan bagian depan cassone, peti berhias tempat menyimpan barang bawaan pengantin di Italia masa Renaisans. Liberale juga dikenal karena menghias buku-buku paduan suara Katedral Siena.","Lukisan ini menampilkan satu adegan dari kisah cinta yang tak diketahui judulnya. Pada pecahan pasangannya, seorang gadis di jendela tampak memanggil seorang pemuda masuk; di sini keduanya bermain catur. Menurut museum, si gadis hampir kalah. Catur adalah gambaran favorit tentang merayu dalam sastra cinta masa itu."],"spots":[["Papan catur","Papan merah-putih dengan bidak gelap; permainan tampaknya hampir usai."],["Si pemuda","Ia menjangkau papan dan tampaknya akan menang."],["Si gadis","Duduk di seberang; di panel pasangannya ia memanggil si pemuda dari jendela."],["Jendela","Di balik jendela yang terbuka tampak bukit dan langit."],["Para pemuda yang menonton","Para pria bersedekap mengikuti permainan."],["Para gadis yang menonton","Para gadis mengintip permainan dari balik tiang."]]},"mirror":{"title":"Wadah cermin dengan pasangan bermain catur","artist":"Tidak diketahui","date":"1325–50","place":"Prancis (Paris)","game":"Catur","medium":"Gading","size":"Diameter 10,2 cm","credit":"Dibeli dengan Dana J. H. Wade, 1940","p":["Cakram gading seukuran telapak tangan ini dulu menutupi sebuah cermin tangan. Di Paris abad ke-14, cermin logam yang digosok mengilap diapit dua lempeng gading lalu dibawa ke mana-mana; ukiran gading seperti ini adalah barang mewah kesukaan kalangan istana dan bangsawan.","Di dalam tenda bertirai, seorang pemuda dan seorang wanita bangsawan bermain catur. Dalam kisah-kisah abad pertengahan, catur melambangkan cinta sekaligus perang. Ada yang menduga pasangan ini Tristan dan Isolde, atau Lancelot dan Guinevere, tetapi tak ada yang tahu pasti. Museum bertanya kepada pengunjungnya: menurutmu siapa yang sedang menang?"],"spots":[["Papan catur","Papan di atas meja berkaki satu, dengan beberapa bidak."],["Si pemuda","Ia menjulurkan tangan untuk melangkah."],["Si wanita","Wanita berkerudung; ujung jarinya menyentuh sebuah bidak."],["Tangan yang terkepal","Tangannya yang lain terkepal di pangkuan. Apakah ia menggenggam bidak yang ditangkapnya?"],["Tenda","Tirai yang diikat di kedua sisi — latar yang sering muncul pada adegan catur di wadah cermin."]]},"morris":{"title":"Sebuah papan permainan (Nine Men’s Morris)","artist":"Peter Flötner","date":"1500–46","place":"Jerman","game":"Nine Men’s Morris","medium":"Cukil kayu","credit":"Dana Abadi Charles W. Harkness, 1923","p":["Cetakan cukil kayu karya Peter Flötner, salah satu pematung paling berbakat di Nürnberg masa Renaisans, yang juga merancang ornamen, perabot, model untuk pandai emas, dan satu set kartu remi yang terkenal karena sindirannya. Di balik sulur daun yang berpilin tersembunyi papan Nine Men’s Morris — “Mühle” dalam bahasa Jerman: tiga persegi bersarang yang dihubungkan di tengah setiap sisi.","Papan ini punya 24 titik. Siapa yang menjajarkan tiga bidaknya (sebuah “gilingan”) boleh mengambil satu bidak lawan. Cetakan seperti ini juga menjadi contoh bagi para perajin, dan museum memamerkan lembaran ini dalam pameran model dan rancangan pandai emas. Tidak tercatat apakah orang bermain langsung di atas kertasnya, atau menyalinnya ke kayu atau logam."],"spots":[["Persegi tengah","Persegi paling dalam, penuh anyaman halus."],["Sudut luar","Sudut persegi luar — salah satu dari 24 titik tempat bidak berdiri."],["Sudut tengah","Sudut persegi tengah juga merupakan titik."],["Garis penghubung","Pita yang menghubungkan ketiga persegi di tengah setiap sisi; bidak juga bergerak di atasnya."],["Topeng","Kartus berpilin dan wajah di atas, bawah, dan samping — ornamen grotesk Renaisans."],["Bingkai sulur anggur","Daun dan buah yang dicukil putih di atas dasar hitam."]]},"leifeng":{"title":"Papan permainan Pagoda Leifeng","artist":"Tidak diketahui","date":"1736–95 (masa Qianlong)","place":"Tiongkok","game":"Permainan balapan","medium":"Cukil kayu; tinta di atas kertas","size":"31 × 29,8 cm","credit":"Dibeli dengan Dana J. H. Wade, 2025","p":["Selembar cetakan untuk dimainkan, dari masa pemerintahan Kaisar Qianlong di Tiongkok era Qing. Petak-petaknya dihuni tokoh-tokoh Legenda Ular Putih: roh ular Bai Suzhen (“Nyonya Putih”), kawannya Xiaoqing (“Si Hijau Kecil”), pemuda Xu Xuan (Xu Xian dalam versi-versi kemudian), dan biksu Fahai, yang akhirnya mengurung Nyonya Putih di bawah Pagoda Leifeng di tepi Danau Barat.","Lintasannya berpilin dari petak bertuliskan 起馬, “berangkat”, menuju pagoda di tengah. Para pemain mungkin berlomba menyusuri kisahnya dengan dadu, seperti Permainan Angsa di Barat; aturannya tidak tercatat. Menurut museum, cetakan berwarna seperti ini dijual di kota-kota dan digantung di dinding sebagai bagian budaya visual perkotaan — setiap warna dicetak dari papan ukir tersendiri."],"spots":[["Mulai","Petak bertuliskan 起馬, “berangkat” — kemungkinan titik awal."],["Nyonya Putih dan Si Hijau Kecil","Roh ular Bai Suzhen dan kawannya Xiaoqing."],["Xu Xuan","Pemuda yang menikahi Nyonya Putih."],["Biksu Fahai","Biksu yang mengurungnya di bawah pagoda."],["Pagoda Leifeng","Pagoda di tepi Danau Barat, Hangzhou, tempat kisahnya berakhir."],["Tengah","Seorang wanita duduk di depan pagoda dan seorang pria berlutut — adegan terakhir kisah ini, dan mungkin garis akhirnya."]]},"tutinama":{"title":"Monyet yang terluka menggigit tangan pangeran, kawan caturnya (dari Tuti-nama, Kisah-Kisah Burung Nuri)","artist":"Dasavanta","date":"sekitar 1560","place":"India (istana Mughal Akbar)","game":"Catur","medium":"Tempera, tinta, dan emas di atas kertas","size":"20 × 14,2 cm (lukisan 10,2 × 10,6 cm)","credit":"Hadiah Ny. A. Dean Perry, 1962","p":["Ilustrasi dari Tuti-nama, “Kisah-Kisah Burung Nuri”, yang dibuat di istana Kaisar Mughal Akbar. Ini salah satu cerita yang dituturkan induk nuri kepada anak-anaknya agar mereka tidak bersahabat dengan jenis makhluk lain, seperti anak-anak rubah. Dalam cerita itu, seekor monyet yang pandai bermain catur sering bermain dengan seorang pangeran.","Suatu hari, di depan para tamu, si monyet melontarkan lelucon kasar; pangeran menamparnya, dan monyet itu menggigit tangan pangeran. Di luar sebelah kanan, para pelayan menyiapkan makanan sementara para tamu menonton dengan tercengang. Tulisan di bawah menyebut nama Dasavanta, yang kelak menjadi salah satu empu paling termasyhur di istana Mughal; semasa muda ia melapisi bagian bawah lukisannya dengan warna biru yang sejuk."],"spots":[["Si monyet","Menggigit tangan pangeran, kawan caturnya."],["Sang pangeran","Pangeran yang tangannya digigit."],["Papan catur","Papan berpetak merah di lantai."],["Para tamu yang tercengang","Para tamu yang diundang."],["Menyiapkan makanan","Di luar, pelayan menaruh periuk di atas api."],["Teks Persia","Di atas, kisahnya ditulis dalam bahasa Persia."]]},"teniers":{"title":"Permainan backgammon","artist":"David Teniers","date":"1640-an","place":"Flandria","game":"Backgammon","medium":"Cat minyak di atas kayu, dipindahkan ke kanvas","size":"59 × 80,6 cm","credit":"Hadiah Tn. dan Ny. Samuel D. Wise, 1943","p":["Pertandingan backgammon bertaruhan besar karya pelukis Flandria, Teniers. Permainan ini sangat tua: bentuk modernnya muncul pada 1400-an, dan nama “backgammon” lahir kira-kira pada masa lukisan ini dibuat. Pada 1600-an ia sangat populer dan sering dimainkan dengan taruhan uang.","Para penonton mengerumuni kedua pemain, dan di dekat dinding seseorang mencatat skor. Dari para perempuan yang menonton — salah satunya menjulurkan kepala dari jendela — museum menduga ruangan ini adalah ruang judi di sebuah rumah bordil. Adegan permainan seperti ini kerap membawa pesan moral: berjudi itu bodoh, bahkan jahat, dan membuang waktu."],"spots":[["Papan","Papan backgammon yang terbuka di atas meja; permainan sedang berlangsung."],["Pria berbaju putih","Pemain yang membelakangi kita, menjangkau bidaknya."],["Pria bertopang dagu","Lawannya, termenung."],["Pencatat skor","Seorang pria menandai papan di dinding — skor, atau taruhan?"],["Perempuan di jendela","Seorang perempuan tua menonton dari atas."],["Ruang belakang","Di belakang, para pria minum di dekat seorang perempuan muda."]]},"imari":{"title":"Piring dengan dua pria bermain go","artist":"Tidak diketahui","date":"abad ke-18","place":"Jepang (zaman Edo)","game":"Go","medium":"Porselen cetak dengan lukisan email di atas glasir (Hizen, gaya Imari)","size":"2,4 × 13,8 cm","credit":"Koleksi Severance dan Greta Millikin, 1964","p":["Di piring persegi kecil ini, dua pria bermain go di bawah pohon pinus: yang berbaju kuning duduk menghadap papan yang diletakkan langsung di tanah, sementara lawannya yang berbaju hijau bersandar ke pohon.","Ini porselen Imari dari Hizen (kini Saga dan Nagasaki), dan warna hijaunya mengingatkan pada email Kutani. Piring ini dibuat untuk ekspor, ketika Jepang telah menggantikan Tiongkok sebagai pemasok utama porselen ke Eropa."],"spots":[["Papan go","Papan bergaris yang diletakkan langsung di tanah."],["Pria berbaju kuning","Duduk menghadap papan."],["Pria berbaju hijau","Lawannya, bersandar ke pohon sambil tersenyum."],["Pohon pinus","Pinus yang menjulurkan dahannya di atas mereka."],["Bingkai merah","Bingkai merah bersudut potong mengelilingi adegan."]]},"shoei":{"title":"Empat Keterampilan (satu dari sepasang layar lipat)","artist":"dikaitkan dengan Kanō Shōei","date":"akhir abad ke-16–awal abad ke-17","place":"Jepang (zaman Momoyama)","game":"Go","medium":"Satu dari sepasang layar lipat enam panel; tinta dan sedikit warna di atas kertas","size":"153 × 358,6 cm","credit":"Dana John L. Severance, 1979","p":["Layar lipat enam panel yang dikaitkan dengan Kanō Shōei dari aliran Kanō. Bersama pasangannya, layar ini menggambarkan “empat keterampilan” yang diharapkan dari seorang pria terpelajar Tiongkok: memainkan qin, bermain qi (go), kaligrafi, dan melukis. Di sini para pria Tiongkok terpandang beserta pelayan mereka bersantai di padang di bawah pohon pinus.","Di tengah, dua orang bermain go sementara orang ketiga menonton. Di dekatnya, sebuah meja memuat buku dan qin yang masih di dalam sarung kainnya, menunggu dimainkan. Adegan ini menyeimbangkan kesenangan dan tata krama. Museum mencatat bahwa salah satu pelayan teralihkan perhatiannya oleh gerak ikan di air."],"spots":[["Papan go","Papan berkaki; dua pria bermain berhadapan."],["Para pria","Dua pemain dan orang ketiga yang menonton."],["Meja","Kemungkinan meja berisi buku dan qin dalam sarungnya."],["Para pelayan","Pelayan yang menunggu di dekat meja."],["Pelayan yang teralihkan","Berbaring di tepi air, memperhatikan ikan."],["Pinus","Pinus besar membentangkan dahannya di atas adegan."]]},"umaya":{"title":"Sekat Lipat Istal Kuda (go dan shogi di beranda)","artist":"Tidak diketahui","date":"Awal abad ke-16","place":"Jepang (zaman Muromachi)","game":"Go dan shogi","medium":"Satu dari sepasang sekat lipat enam panel; tinta, warna, dan emas di atas kertas","size":"146,1 × 346,6 cm","credit":"Edward L. Whittemore Fund, 1934","p":["Sekat lipat dari enam panel yang disambung ini adalah satu dari sepasang. Kuda-kuda berharga di kandangnya mungkin tema utamanya, tetapi banyak hal terjadi di beranda depan.","Di sana orang-orang saling menantang dalam dua permainan berbeda: go di kiri dan shogi di kanan. Menurut museum, suasana yang hidup muncul dari perpaduan kuda yang gelisah dan strategi tenang permainan. Di Jepang monyet dianggap melindungi kuda, dan kadang dipelihara di istal."],"spots":[["Papan go","Papan bergaris halus dengan batu hitam."],["Dua pria bertopi hitam","Pria bertopi eboshi hitam tinggi: yang berbaju hijau menjangkau papan, yang berbaju merah menonton."],["Papan shogi","Petaknya besar — jauh lebih sedikit daripada papan go."],["Lawan yang tertawa","Seorang biksu berkepala gundul mengambil bidak, sementara pria di depannya memegang kepala sambil tertawa keras. Apakah seseorang baru mencetak angka?"],["Seekor monyet","Di ujung beranda — monyet berbaju merah?"],["Seekor kuda","Kuda hitam mengangkat kaki depannya, ditahan tali."]]},"goryeo":{"title":"Kendi seladon bertatah dengan pemain go","artist":"Tidak diketahui","date":"Abad ke-13","place":"Korea (Dinasti Goryeo)","game":"Go (baduk)","medium":"Seladon dengan tatahan slip putih dan hitam","size":"Tinggi 20,4 cm, diameter 14,3 cm","credit":"Hibah John L. Severance, 1917","p":["Kendi seladon Goryeo dengan cerat dan pegangan. Teknik tatahan — menggores garis pada tanah liat, mengisinya dengan slip putih dan hitam, lalu mengglasir dan membakarnya — adalah keahlian khas perajin Goryeo; di sini, di dalam bingkai bundar, dua sosok yang duduk di bawah pohon dedalu tampak putih.","Di antara mereka ada papan, dan museum membandingkan adegan ini dengan gambar orang bermain go — baduk dalam bahasa Korea. Bermain kecapi, go, kaligrafi, dan lukisan adalah “empat keahlian” cendekiawan terpelajar, dan pertemuan mereka yang anggun juga menjadi motif kerajinan. Seladon Korea bergambar manusia jarang ditemukan."],"spots":[["Papan","Papan di antara keduanya, berupa kotak putih."],["Sosok di kiri","Duduk menghadap papan."],["Sosok di kanan","Lawannya, duduk di seberang."],["Pohon dedalu","Ranting dedalu menjuntai di atas mereka, digambar dengan slip hitam."],["Bingkai awan","Ulir seperti awan mengelilingi bingkai bundar."],["Retak glasir","Retakan halus pada glasir. Terbentuk saat mendingin karena tanah liat dan glasir menyusut berbeda."]]},"kangra":{"title":"Pasangan bermain chaupar di teras","artist":"Tidak diketahui","date":"sekitar 1790–1800","place":"India (Pahari, mazhab Kangra)","game":"Chaupar","medium":"Gambar dengan sketsa awal oker merah","size":"19,4 × 13,2 cm","credit":"Edward L. Whittemore Fund, 1936","p":["Gambar karya seniman Kangra, di perbukitan Pahari di kaki Himalaya. Sketsa pertama dibuat dengan merah (oker merah), lalu dirapikan dengan hitam. Tanpa warna di atasnya, setiap garis tokoh dan benda dapat diikuti.","Seorang pria dan wanita duduk di teras di kedua sisi papan berbentuk salib, bermain chaupar — permainan balap kuno India di salib yang sama dengan pachisi, dimainkan dengan melempar dadu panjang (pasa). Petak-petaknya belum digambar di papan. Para pelayan melayani pasangan itu."],"spots":[["Papan salib","Papan berbentuk salib di lantai. Petaknya belum digambar."],["Sang wanita","Telapak tangannya terbuka ke atas — hendak melempar dadu?"],["Sang pria","Bersorban dengan hiasan bulu; ia menjangkau papan."],["Pelayan di kiri","Memegang botol kecil dan mengulurkan kain."],["Pelayan di kanan","Memegang alat bergagang panjang dan wadah kecil."],["Sketsa merah","Di sekitar sorban, sketsa merah tampak di bawah garis hitam."]]},"vuillard":{"title":"Permainan Dam (dari Pemandangan dan Interior)","artist":"Édouard Vuillard","date":"1899","place":"Prancis","game":"Dam","medium":"Litografi berwarna (state III/III); dicetak oleh Auguste Clot, diterbitkan oleh Ambroise Vollard","size":"Gambar 33 × 25,7 cm (kertas 38 × 30,8 cm)","credit":"Hibah Hanna Fund, 1951","p":["Ambroise Vollard, pedagang lukisan impresionis, juga penerbit cetakan grafis yang penting. Pada 1895 ia memesan album 12 litografi berwarna dari Pierre Bonnard, lalu menerbitkan banyak album lain, di antaranya Pemandangan dan Interior karya Vuillard yang dicetak oleh master pencetak Auguste Clot.","Bonnard dan Vuillard termasuk kelompok Nabis — “para nabi” dalam bahasa Ibrani — yang mencari seni baru tempat bentuk dan warna sendiri mengungkapkan perasaan, dan gemar melukis kehidupan kota serta keluarga. Di ruangan yang penuh motif, dua pria berhadapan di depan papan dam sementara seorang wanita berdiri menonton. Dalam bahasa Prancis permainan ini disebut “dames”; catatan pensil di kiri bawah berbunyi “partie de dames”, satu permainan dam."],"spots":[["Papan","Papan kotak-kotak kecil dengan bidak yang tersusun."],["Pria di kiri","Pria berjanggut mengulurkan tangan ke atas papan."],["Pria di kanan","Lawannya membungkuk di atas papan di kursi berlengan, setengah tertutup wanita yang berdiri."],["Wanita yang berdiri","Dengan tangan di dagu, ia mengikuti permainan."],["Lampu","Lampu di dekat dinding. Kertas dinding dan pelapis kursi penuh motif."],["Catatan pensil","Di kiri bawah dengan pensil: “partie de dames” — satu permainan dam."]]},"talbot":{"title":"Para Pemain Catur (foto awal)","artist":"Diatribusikan kepada William Henry Fox Talbot","date":"sekitar 1843–47","place":"Inggris","game":"Catur","medium":"Cetak kertas bergaram","size":"19,9 × 15 cm","credit":"Dibeli dengan dana dari Tuan dan Nyonya Everett Kovler","p":["Proses negatif-positif ciptaan Talbot, dengan salinan tak terbatas yang dimungkinkannya, mendominasi fotografi hingga era digital. Eksperimen awalnya menunjukkan minat pada sains sekaligus cita-cita artistik, dan para peneliti memastikan ia memotret pemain catur sepuluh kali atau lebih.","Namun foto ini mungkin bukan karyanya: cetakan ini dan versi lain adegan yang sama tidak bertanda tangan dan memakai kertas berbeda dari biasanya. Yang difoto kemungkinan fotografer Antoine Claudet dan asisten Talbot, Nicolaas Henneman; riset terbaru menduga foto-foto ini dibuat di studio Claudet, berpindah ke Henneman, lalu sampai ke Talbot sebagai bagian pembayaran utang (catatan museum)."],"spots":[["Papan","Papan catur di meja, bidaknya berjajar."],["Pria bertopi tinggi","Dengan topi masih terpasang, ia meraih bidak."],["Pria yang berpikir","Tangan di dagu, lawannya mengamati papan."],["Tirai","Tirai tergantung di belakang — latar untuk pemotretan?"],["Topi lain","Topi tinggi kedua terletak di dudukan sebelah kanan."]]},"pvl":{"title":"Pria Bermain Dadu","artist":"Master PVL","date":"sekitar 1520","place":"Belanda (Negeri-Negeri Rendah)","game":"Dadu","medium":"Grafir di atas kertas","size":"9,4 × 9,4 cm (bundar)","credit":"Koleksi Charles Hack dan Hearn Family Trust, dibeli 2023","p":["Karya seorang pengukir tanpa nama yang aktif di Negeri-Negeri Rendah awal abad ke-16, disebut Master PVL dari monogram “PVL” di kiri bawah. Pada cetakan bundar yang muat di telapak tangan, garis halus yang rapat membangun kedalaman ruangan dan tekstur pakaian.","Di meja ada dua dadu. Seorang pria yang mencondongkan badan dan pemuda berkerah bulu menunjuk dan berdebat — mungkin soal angka. Di belakang, para wanita menonton, dan di bawah meja ada kendi anggur. Dadu sejak zaman kuno terkait dengan judi dan berulang kali dilarang."],"spots":[["Dadu","Dua dadu bergulir di meja."],["Tangan yang menunjuk","Dua jari bertemu di meja — berdebat soal angka?"],["Pria bertopi lebar","Mencondongkan badan; lengan kembung bersayat adalah mode masa itu."],["Pemuda berkerah bulu","Bertopi besar dan berkerah bulu."],["Para wanita yang menonton","Para wanita mengintip permainan dari belakang."],["Monogram","“PVL” di kiri bawah — satu-satunya petunjuk nama senimannya."]]},"kiyohiro":{"title":"Para Pemain Sugoroku","artist":"Torii Kiyohiro","date":"sekitar 1750","place":"Jepang (zaman Edo)","game":"Ban-sugoroku","medium":"Cetak balok kayu berwarna (benizuri-e), ōban; penerbit Urokogataya","size":"43,5 × 29,3 cm","credit":"Koleksi Clarence Buckingham","p":["Torii Kiyohiro adalah seniman ukiyo-e yang aktif sekitar 1737 hingga 1776. Ini adalah benizuri-e, dicetak dengan sedikit balok warna — merah muda beni, hijau, dan sejenisnya — pada tahun-tahun sebelum nishiki-e berwarna penuh muncul pada 1765.","Permainan di atas dudukan hitam adalah ban-sugoroku: dua pemain melempar dadu dan menjalankan bidak putih dan hitam, dan yang pertama mengeluarkan semua bidaknya menang. Permainan ini sekeluarga dengan backgammon, dan cetakan ukiyo-e sering menggambarkan perempuan memainkannya. Di belakang, seorang perempuan mengisap pipa panjang sambil menonton."],"spots":[["Papan","Papan sugoroku di atas dudukannya, dengan bidak putih dan hitam."],["Sosok di kiri","Mengulurkan tangan untuk menjalankan bidak."],["Perempuan di kanan","Membungkuk di atas papan, lawannya mengamati bidak."],["Perempuan berpipa","Dengan pipa kiseru panjang, mengikuti permainan dari belakang."],["Tangan terangkat","Perempuan di kanan mengangkat benda kecil hitam — wadah pengocok dadu?"],["Tanda tangan","“Torii Kiyohiro hitsu” dengan cap penerbit Urokogataya."]]},"ingram":{"title":"Permainan Catur Tiongkok","artist":"John Ingram, menurut François Boucher","date":"1741–63","place":"Prancis (Paris)","game":"Xiangqi","medium":"Etsa dan grafir","size":"Kertas 39,4 × 27,7 cm (pelat 24,5 × 16,4 cm)","credit":"Koleksi Elisha Whittelsey, 1966","p":["Gambar pelukis Prancis François Boucher yang diukir oleh John Ingram kelahiran London. Ingram pindah ke Paris dan, antara 1741 dan 1763, membuat serangkaian cetakan menurut chinoiserie Boucher — Tiongkok seperti yang dibayangkan orang Eropa. Judul di bawahnya berbunyi “LE JEU D'ECHETS CHINOIS”, permainan catur Tiongkok.","Seorang wanita bersanggul tinggi menjalankan bidak di papan di pangkuannya, sementara seorang anak kecil menonton. Permainan ini dianggap xiangqi, padahal bidak xiangqi asli semuanya cakram pipih, sedangkan di sini bidak tinggi berdiri di samping bidak kecil persegi. Pohon palem dan sosok yang duduk di atas guci pun lebih mencerminkan negeri jauh yang diimpikan Eropa kala itu daripada Tiongkok sebenarnya."],"spots":[["Papan dan bidak","Papan di pangkuan, dengan bidak tinggi dan persegi. Bidak xiangqi asli berupa cakram pipih."],["Tangan di bidak","Tangan kanannya menjalankan bidak."],["Bertopang dagu","Tangan kirinya di dagu, ia memandang papan."],["Anak yang menonton","Seorang anak berdiri di dekat papan, mengikuti permainan."],["Sosok di atas guci","Sosok yang duduk bersila di atas guci besar."],["Judul dan nama","“Dessiné par Fr. Boucher”, “Gravé par Ingram” dan judul “LE JEU D'ECHETS CHINOIS”."]]},"posada":{"title":"Permainan Angsa","artist":"José Guadalupe Posada","date":"1909","place":"Meksiko","game":"Permainan angsa","medium":"Cetak timbul dari pelat seng di atas kertas","size":"29,3 × 39,4 cm","credit":"William McCallin McKee Memorial Endowment","p":["Lembar untuk bermain buatan pengukir Meksiko Posada — terkenal dengan tengkorak “calavera”-nya — untuk penerbit Mexico City Antonio Vanegas Arroyo. Pita di kiri bawah bertuliskan “JUEGO DE LA OCA” (permainan angsa), dan lintasannya berpilin dari petak 1 sampai 63 di tengah.","Di tengah tercetak aturannya (EXPLICACION): lemparan pertama 5 dan 4 menuju 26, 6 dan 3 menuju 53. Yang mendarat di angsa (seekor burung) menghitung lagi sebanyak itu; di penginapan (Venta, 19) menunggu dua giliran; di sumur (Poso, 31) dan penjara (Carcel, 52) tinggal sampai pemain lain datang; labirin (42) mengembalikan ke 39, dan maut (Muerte, 58) ke awal. Harus tepat mendarat di 63. Di petak tertentu pemain juga membayar taruhan: ini juga permainan judi."],"spots":[["Aturan","“EXPLICACION” di tengah: efek tiap petak dan kapan membayar taruhan."],["Petak 1","Start. Dari sini lintasan berpilin ke tengah."],["Sumur (31)","Sumur seperti air mancur. Yang jatuh tinggal sampai pemain lain datang."],["Maut (58)","Petak tengkorak: kembali ke awal."],["Pita judul","“JUEGO DE LA OCA” di pita kiri bawah, dengan anak-anak bermain di bawahnya."],["Nama penerbit","Pita sang dewi bertuliskan “IMPRENTA DE A. VANEGAS ARROYO”, penerbit banyak cetakan Posada."]]},"jintile":{"title":"Ubin dengan wanita bermain permainan papan","artist":"Tidak diketahui","date":"Abad ke-13","place":"Tiongkok (Dinasti Jin)","game":"Permainan papan (kemungkinan go)","medium":"Tembikar (relief cetak)","size":"Tinggi 27,3 cm, lebar 24,8 cm, tebal 5,4 cm","credit":"Dibeli dengan sumbangan Friends of Asian Art, 2002","p":["Ubin relief dari masa Jin (1115–1234), dinasti bangsa Jurchen yang menguasai Tiongkok utara. Di bawah pohon berbunga, dua wanita duduk berhadapan di atas panggung dengan papan di antara mereka.","Papannya berpetak halus, jadi kemungkinan mereka bermain go. Wanita di kanan mencondongkan badan dan menunjuk papan, sementara yang di kiri memperhatikan. Banyak makam masa Jin di Tiongkok utara dilapisi bata relief bergambar kehidupan sehari-hari, dan ubin ini kemungkinan menghiasi makam semacam itu."],"spots":[["Papan","Papan berpetak halus, kemungkinan papan go."],["Tangan yang menunjuk","Wanita di kanan menunjuk papan. Langkah berikutnya?"],["Wanita di kiri","Rambut disanggul tinggi, ia memandang papan."],["Wanita di kanan","Mencondongkan badan ke papan."],["Pohon berbunga","Dahan pohon berbunga terbentang di atas mereka."],["Panggung","Panggung tempat mereka duduk, dengan hiasan bergelombang di antara kakinya."]]},"kyosai":{"title":"Kentut Mengacaukan Permainan Go (dari album sketsa)","artist":"Kawanabe Kyōsai","date":"Pertengahan–akhir abad ke-19","place":"Jepang (zaman Edo–Meiji)","game":"Go","medium":"Satu bukaan dari album lipat 26 lembar ganda; tinta dan warna di atas kertas","size":"Album (tertutup) 28 × 18 cm","credit":"Hibah Anne dan Anthony d’Offay untuk menghormati Evan Turner","p":["Satu adegan dari album sketsa Kawanabe Kyōsai (1831–1889), pelukis yang aktif dari akhir keshogunan hingga era Meiji, digambar dengan sapuan kuas cepat dan bebas di halaman album lipat. Terlatih dalam teknik ketat aliran Kanō, Kyōsai juga digemari karena gambar setan, karikatur, dan satirenya.","Judul dari museum sudah menjelaskan semuanya: “Kentut Mengacaukan Permainan Go.” Di kiri seorang pria bertopi hitam membungkuk; di kanan papan go terbang, mangkuk menumpahkan hujan batu, dan lawannya jatuh terlentang. Permainan serius hancur dalam satu letupan — Kyōsai merekam dengan kuasnya yang cepat humor kentut Jepang kuno yang sudah ada dalam gulungan abad pertengahan."],"spots":[["Pria bertopi hitam","Membungkuk dengan pantat menonjol — biang keributan?"],["Papan yang terbang","Papan go bergaris melayang miring."],["Mangkuk dan batu","Dua mangkuk terguling, batu-batunya berhamburan."],["Kipas","Kipas terbuka ikut terbang di dekat papan."],["Lawan yang terjungkal","Terlentang dengan mata terbelalak."],["Sapuan kuas","Garis tinta yang kuat, seakan dibuat sekali jadi tanpa sketsa."]]},"yokuts":{"title":"Nampan Permainan Untung-untungan","artist":"Penganyam Yokuts (nama tidak diketahui)","date":"sekitar 1900","place":"Amerika Serikat (dekat Dunlap, California)","game":"Huuchuish (dadu kulit kenari)","medium":"Serat tumbuhan (anyaman gulung)","size":"Tinggi 5,1 cm, diameter 61 cm","credit":"Dibeli dengan dana dari Ny. Leonard S. Florsheim Jr.","p":["Banyak masyarakat adat California memainkan permainan untung-untungan. Nampan ini dipakai untuk huuchuish, permainan dadu yang hanya dimainkan perempuan: delapan dadu kulit kenari dilempar ke nampan, dan skor dihitung dengan batang kecil.","Motif melingkar yang dianyam di nampan menggambarkan permainan itu sendiri — dadu, batang penghitung, dan para pemainnya (catatan museum). Ini alat permainan yang membawa gambar permainannya sendiri. Di foto, dadu kulit kenari diletakkan di atas dan di sekitar nampan."],"spots":[["Para pemain","Sosok-sosok mengitari tepi — orang yang ikut bermain."],["Batang penghitung","Kumpulan garis tegak pendek: batang untuk menghitung skor."],["Motif bundar","Motif bundar kecil — mungkin dadunya?"],["Dadu kenari","Dadu dari kulit kenari. Delapan dilempar ke nampan."],["Pita segitiga","Pita segitiga gelap melingkar penuh."],["Pusat","Anyaman berpilin keluar dari tengah, dikelilingi lingkaran putus-putus."]]},"hokkei":{"title":"Ushiwakamaru Mengalahkan Benkei dalam Sugoroku","artist":"Totoya Hokkei","date":"sekitar 1825","place":"Jepang (zaman Edo)","game":"Ban-sugoroku","medium":"Surimono (cetak balok kayu berwarna, shikishiban)","size":"21,8 × 19,1 cm","credit":"Hibah Helen C. Gunsaulus","p":["Sebuah surimono karya Totoya Hokkei (1780–1850), murid Hokusai. Surimono adalah cetakan pesanan pribadi — sering oleh kelompok puisi, dengan sajak mereka sendiri — dan dibuat lebih mewah daripada ukiyo-e komersial, dengan kertas bagus dan pigmen logam.","Ushiwakamaru, nama kecil pahlawan Minamoto no Yoshitsune, dan biksu prajurit raksasa Benkei. Pertemuan mereka yang terkenal adalah duel di Jembatan Gojō di Kyoto, tetapi di sini pertarungan menjadi permainan sugoroku: si anak duduk tenang di balik papan, sementara Benkei dengan tombak di punggung menggaruk kepala karena kalah. Tampaknya ini gubahan yang jenaka."],"spots":[["Papan sugoroku","Papan berbentuk kotak dengan bidak putih dan hitam."],["Benkei menggaruk kepala","Berbaju zirah lengkap, yang kalah menggaruk kepala."],["Ushiwakamaru","Sang pahlawan muda, duduk di balik papan."],["Tombak","Mata naginata besar milik Benkei."],["Sajak","Sajak di kanan atas — mungkin dari kelompok yang memesan cetakan ini."],["Tanda tangan","Tanda tangan Hokkei di bingkai kanan bawah."]]},"vorsterman":{"title":"Para Pemain Backgammon (adegan malam)","artist":"Lucas Emil Vorsterman, menurut Adam de Coster","date":"sekitar 1630","place":"Flandria (Antwerpen)","game":"Backgammon","medium":"Grafir di atas kertas warna gading","size":"Gambar 25,5 × 34,4 cm","credit":"Koleksi Bernard F. Rogers","p":["Adam de Coster adalah pelukis terkemuka adegan malam bercahaya lilin di Antwerpen sekitar 1630, ketika Vorsterman di kota yang sama mengukir karya pelukis populer sezamannya. Murid Rubens ini berselisih dengan gurunya lalu pergi ke Inggris, dan sesudahnya membuat grafir yang lebih kuat kontrasnya, bergaya, ala Caravaggio seperti ini.","Di sekeliling meja di ruangan gelap, para pria berkumpul di depan papan backgammon. Mengikuti cara De Coster mengolah cahaya, dua nyala lilin menerangi wajah-wajah di sekitar meja (catatan museum). Di kanan, seorang pemuda pemain lute memandang ke arah kita."],"spots":[["Papan","Papan backgammon yang terbuka seperti kotak di meja."],["Lilin","Lilin di kandilnya; nyalanya menerangi wajah-wajah."],["Pria berpipa","Bertopi lebar, ia mengisap pipa sambil menonton."],["Pria yang membelakangi","Membungkuk dengan tangan di meja."],["Pemain lute","Pemuda dengan lute yang tersenyum pada kita."],["Nama","“A. De Coster pi.” di kiri bawah, “Vorsterman” di kanan bawah."]]},"zorn":{"title":"Para Pemain Catur","artist":"Anders Zorn","date":"1891","place":"Swedia","game":"Catur","medium":"Etsa di atas kertas laid warna gading","size":"Gambar 13,5 × 9,6 cm (pelat 13,9 × 10 cm)","credit":"Koleksi etsa Anders Zorn milik Wallace L. DeWolf dan Charles Deering","p":["Etsa karya seniman Swedia Anders Zorn (1860–1920), yang termasyhur secara internasional lewat potret cat minyak dan cat air serta meninggalkan banyak karya grafis. Pelatnya tak lebih besar dari telapak tangan.","Cukup dengan garis-garis miring cepat yang ditumpuk, ruangan gelap dan dua orang muncul dari tembaga. Pria di depan, membelakangi kita, membungkuk di atas papan; sosok di seberang menunduk memikirkan langkah berikutnya. Bidak-bidaknya digambar dengan goresan tipis. Siapa yang menjadi model tidak tercatat."],"spots":[["Papan dan bidak","Bagian terang di bawah adalah papan; goresan tegak pendek adalah bidak."],["Pria di depan","Membelakangi kita, membungkuk di atas papan."],["Lawan","Menunduk, menatap papan."],["Latar gelap","Kedalaman ruangan dari garis-garis tegak."],["Garis miring","Mantelnya dibuat dari goresan diagonal cepat yang ditumpuk."],["Tanda tangan","Ditandatangani “Zorn” dengan pensil di bawah pelat."]]},"harunobu-sugoroku":{"title":"Menonton Permainan (sugoroku)","artist":"Suzuki Harunobu","date":"sekitar 1766","place":"Jepang (zaman Edo)","game":"Ban-sugoroku","medium":"Cetak balok kayu berwarna (chūban, surimono)","size":"28,5 × 21 cm","credit":"Koleksi Clarence Buckingham","p":["Suzuki Harunobu (1725?–1770) adalah tokoh utama ketika cetakan nishiki-e berwarna penuh, dicetak dari banyak balok, lahir sekitar 1765. Ini surimono terbitan pribadi, dan warnanya yang lembut berlapis menunjukkan kebaruannya.","Di ruangan dengan bunga plum, dua gadis bermain di papan sugoroku berbentuk kotak sementara gadis ketiga berdiri memandanginya. Bidak putih dan hitam berjajar di papan; gadis di kiri menjalankan bidak dan yang di kanan menjangkau papan. Pintu geser di belakang dilukis air terjun dan pohon pinus."],"spots":[["Papan sugoroku","Papan ban-sugoroku berbentuk kotak dengan bidak putih dan hitam."],["Gadis di kiri","Berkimono motif bangau kertas, menjalankan bidak."],["Gadis di kanan","Membungkuk menjangkau papan."],["Penonton","Berdiri menonton permainan, memegang benda bergagang panjang."],["Plum","Plum putih menjulurkan dahannya dari atas."],["Pintu berlukis","Pintu geser berlukis air terjun dan pinus."]]},"kota":{"title":"Maharao Kishor Singh II dari Kota Memuja Krishna sebagai Brij Rajji","artist":"Tidak diketahui","date":"sekitar 1825","place":"India (Rajasthan, Kota)","game":"Pachisi","medium":"Tempera getah, perak, dan emas di atas kertas","size":"24,5 × 18,8 cm","credit":"James Albert and Mary Gardiner Ford Memorial Fund","p":["Penguasa negara kepangeranan kecil Kota (berkuasa 1819–28), berpakaian pendeta sekte Pushti Marg, mempersembahkan pelita berapi lima. Di kuil kecil di atas altar berdiri arca logam Krishna diapit dua permaisuri — ikon yang hanya dipuja di Kota.","Banyak lampu kaca bergantung dari langit-langit, dan di anak tangga menuju altar ditata mainan dan permainan untuk menghibur Krishna dan kawan-kawannya: gajah kuningan, sapi perak, bola, dan papan pachisi (catatan museum). Kain merah berbentuk salib itulah papannya — pachisi dipersembahkan sebagai mainan sang dewa."],"spots":[["Papan pachisi","Kain merah berbentuk salib di anak tangga: papan pachisi."],["Gajah","Dua gajah kuningan di samping papan."],["Bola","Bola keemasan di anak tangga atas."],["Krishna","Arca Krishna dan dua permaisuri di kuil kecil."],["Penguasa dan pelita","Berpakaian pendeta, ia mempersembahkan pelita berapi lima."],["Lampu kaca","Banyak lampu kaca bergantung dari langit-langit."]]},"coyote":{"title":"Permainan Koyote","artist":"Pengikut José Guadalupe Posada","date":"Tanpa tanggal","place":"Meksiko","game":"Koyote dan ayam (sekeluarga dengan rubah dan angsa)","medium":"Cetak timbul dari pelat seng di atas kertas","size":"38,2 × 30,5 cm","credit":"William McCallin McKee Memorial Endowment","p":["Lembar untuk bermain, dicetak timbul dari seng seperti lembar-lembar yang dibuat Posada untuk percetakan rakyat Mexico City. Di atas tertulis “JUEGO DEL COYOTE” (permainan koyote); di sekelilingnya, koyote menyerbu kandang ayam dan seorang pria mengayunkan tongkat untuk mengusir salah satunya. Pita di bawah berbunyi “Milik Ildefonso T. Orellana”.","Aturannya tercetak di “EXPLICACION” di bawah: dua pemain, satu memegang lima belas ayam dan satu lagi seekor koyote. Ayam bergerak maju atau ke samping tetapi tak pernah mundur; koyote bergerak ke segala arah dan memakan ayam dengan melompatinya bila titik di belakangnya kosong. Ayam menang jika berhasil mengurung koyote. Ini permainan berburu yang sama dengan rubah dan angsa dari Eropa."],"spots":[["Tempat koyote","Kepala koyote di lingkaran tengah: koyote mulai dari sini."],["Tempat ayam","Lingkaran bergambar ayam: bidak ayam ditaruh di sini."],["Aturan","“EXPLICACION”: bidak, gerakan, dan cara menang."],["Judul","“JUEGO DEL COYOTE” — permainan koyote."],["Koyote mengincar ayam","Di kiri bawah, seekor koyote menerkam ayam."],["Pria bertongkat","Di kanan atas, seorang pria mengangkat tongkat pada koyote."]]},"mons":{"title":"Trictrac untuk Mons (Bergen), 1709","artist":"Pieter Nolpe (pelat dan penerbit)","date":"Pelat 1623–53; dicetak sekitar 1709","place":"Belanda (Amsterdam)","game":"Trictrac (sekeluarga dengan backgammon)","medium":"Etsa, grafir, dan sajak cetak huruf","size":"Kertas 35,8 × 18,6 cm (pelat 12,9 × 17,5 cm)","credit":"","p":["Empat pria bermain trictrac di sebuah meja. Menurut catatan museum, huruf A–D menandai Adipati Marlborough, Elektor Bayern, Tuan Ouwerkerk, dan Adipati Villeroy. Ini cetakan satir tentang pengepungan dan perebutan Mons (Bergen dalam bahasa Belanda) oleh Sekutu dari Prancis pada 1709, digambarkan sebagai permainan dengan kota sebagai taruhannya. Di ruang belakang (E), Raja Felipe V dari Spanyol bersama seorang wanita.","Pelatnya bertanda tangan Pieter Nolpe sebagai pembuat dan penerbit, tetapi Nolpe wafat awal 1650-an — kemungkinan pelat tua abad ke-17 dicetak ulang dengan tambahan huruf dan sajak baru. Sajak di bawah dibuka dengan menyebut permainan para tuan besar tak lain tiktak dan verkeer (dua permainan sekeluarga), lalu mengejek tiap pemain."],"spots":[["Papan","Papan trictrac di meja: taruhannya sebuah kota."],["A, Marlborough","Berdiri memandang papan — jenderal Inggris pemimpin Sekutu."],["B, Elektor Bayern","Tanpa topi, terenyak di kursinya."],["C, Ouwerkerk","Bertopi bulu — jenderal Belanda."],["E, ruang belakang","Di kamar belakang, Felipe V bersama seorang wanita."],["Sajak","Sajak berbahasa Belanda di bawah, mengejek pemain A sampai E."]]},"stembus":{"title":"Kotak Suara: Permainan Angsa Politik","artist":"Johan Michaël Schmidt Crans (pembuat cetakan)","date":"1867","place":"Belanda","game":"Permainan angsa (satire)","medium":"Litografi","size":"66 × 50 cm","credit":"","p":["Cetakan satir berbentuk permainan angsa. Cetakan ini terbit bersama mingguan De Nederlandsche Spectator, no. 9, 2 Maret 1867, dengan lembar aturan terpisah (catatan museum). Petak-petaknya berisi potret para menteri saat itu.","Permainan dimulai di Binnenhof, gedung parlemen di Den Haag, dan berakhir di tengah, petak 64 “Insulinde” — nama puitis Hindia Belanda — tempat potret menteri Pieter Mijer digantung dari Pulau Jawa. Mijer beralih dari Menteri Urusan Jajahan menjadi Gubernur Jenderal Hindia, dan pengangkatan itu memicu badai politik. Petak tambahan, satu lebih dari 63 yang biasa, kemungkinan ada demi lelucon penutupnya."],"spots":[["Start","Bangunan di kiri atas: permainan dimulai di Binnenhof, Den Haag."],["Potret Mijer","Petak 63: potret berbingkai Pieter Mijer, digantung dengan tali dari pulau."],["Insulinde 64","Pulau dan angka 64 di tengah: garis akhir."],["Kotak suara","“DE STEMBUS” (kotak suara) di kanan bawah: kotak dalam judul."],["Para menteri","Wajah para menteri saat itu menatap dari petak-petak."],["Ayam jantan","Seekor ayam jantan di satu petak; apa yang disindirnya tidak diketahui."]]},"koorai":{"title":"Orang Korea di Depan Permainan Papan (dari Nippon karya Siebold)","artist":"James Erxleben (litografer), menurut rancangan “Toioske”","date":"1832–52","place":"Belanda (Leiden) / orang Korea","game":"Permainan papan (kemungkinan go)","medium":"Litografi bernada, diwarnai tangan","size":"Kertas 38 × 55,5 cm","credit":"Hibah F. G. Waller","p":["Satu lembar dari NIPPON, karya besar dokter kelahiran Jerman Philipp Franz von Siebold yang diterbitkan di Leiden berdasarkan pengamatannya di pos dagang Belanda di Nagasaki (1823–30). Di kanan atas tertulis “TAB. I” dan di bawah “KOORAI” (Korea), dengan “keluarga nelayan” dalam bahasa Belanda dan Jerman. Erxleben menggambarnya di batu; lembar itu menyebut perancangnya “Toioske”.","Empat pria duduk di tanah mengelilingi papan; di kiri seorang wanita menuntun anak kecil, di kanan seorang pria berdiri dengan tongkat panjang dan kantong. Di depan tergeletak topi hitam bertepi lebar (gat). Papan itu berpetak dengan batu-batu bundar, jadi kemungkinan go (baduk dalam bahasa Korea), meski catatan hanya menyebut “permainan papan”."],"spots":[["Papan","Petak dengan batu bundar: kemungkinan permainan go."],["Topi hitam","Topi hitam bertepi lebar (gat) di tanah."],["Ibu dan anak","Wanita yang menuntun anak sambil menonton."],["Pria yang berdiri","Berdiri dengan tongkat panjang dan kantong."],["Pria yang membungkuk","Berjaket biru, mengamati papan."],["Judul","“KOORAI” (Korea), dengan “keluarga nelayan” dalam bahasa Belanda dan Jerman."]]},"cairo":{"title":"Orang-orang Mengelilingi Permainan Papan di Depan Kedai Kopi (Kairo)","artist":"Délié & Béchard (Hippolyte Délié dan Émile Béchard)","date":"sekitar 1869–90","place":"Mesir (Kairo)","game":"Permainan papan (kemungkinan catur)","medium":"Cetak albumen","size":"10,8 × 16,4 cm","credit":"","p":["Foto karya Hippolyte Délié dan Émile Béchard, fotografer Prancis yang membuka studio di Kairo. Kartonnya bertuliskan nama studio, “dekat Taman Ezbekiya”, dan “Kairo (Mesir)”. Foto semacam ini dibeli para pelancong sebagai kenang-kenangan dari Mesir.","Para pria duduk di tanah di depan toko berjendela kisi, mengelilingi papan di atas dudukan rendah. Bidak-bidak tinggi berdiri di papan, jadi kemungkinan catur (syatranj dalam bahasa Arab), meski catatan museum hanya menyebut “permainan papan”. Semua diam tak bergerak demi pencahayaan yang lama."],"spots":[["Papan dan bidak","Papan di dudukan rendah dengan bidak tinggi: kemungkinan catur."],["Jendela kisi","Jendela berkisi kayu, khas rumah-rumah lama Kairo."],["Pria bertongkat","Duduk memegang tongkat, menonton permainan."],["Keranjang","Keranjang anyaman di tanah."],["Anak yang menonton","Seorang anak mengintip papan dari belakang."],["Nama studio","“AU JARDIN DE L’ESBÉKIEH” dan “CAIRE (EGYPTE)” di karton."]]},"vanmour":{"title":"Sekelompok Orang Armenia Bermain Kartu","artist":"Jean-Baptiste Vanmour","date":"sekitar 1720–37","place":"Kesultanan Utsmaniyah (Istanbul)","game":"Kartu","medium":"Cat minyak di atas kanvas","size":"44,5 × 58,5 cm","credit":"","p":["Vanmour yang lahir di Flandria pergi ke Istanbul pada 1699 bersama duta besar Prancis dan tinggal di kota itu hingga wafat, melukis upacara istana dan kehidupan sehari-hari warganya. Museum mencatat bahwa dari pakaiannya para pria ini adalah orang Armenia.","Di bawah cahaya sebatang lilin besar, para pria dan wanita bermain kartu mengelilingi meja berkain merah. Kartu-kartu yang sudah dibagikan tergeletak di meja, dan sebagian memperhatikan kartu di tangan. Di sudut kiri seorang wanita tua memintal benang. Catatan tidak menyebut permainan apa itu."],"spots":[["Kartu di meja","Kartu di atas meja berkain merah."],["Lilin besar","Sebatang lilin menerangi seluruh kelompok."],["Wanita tua memintal","Wanita tua memintal di sudut kiri."],["Wanita melihat kartunya","Di paling kanan, seorang wanita memandangi kartunya."],["Pria berbulu","Pria bermantel berpinggiran bulu; pakaiannya menandai orang Armenia."],["Mencondongkan badan","Seseorang condong ke meja dengan kartu di tangan."]]},"algiers":{"title":"Tiga Pria Bermain Permainan Papan (Aljir)","artist":"Anonim","date":"1851–1900","place":"Aljazair (Aljir)","game":"Permainan papan (kemungkinan backgammon)","medium":"Cetak albumen","size":"14,0 × 10,0 cm","credit":"","p":["Foto tanpa nama pembuat, dengan tulisan tangan “Alger” (Aljir) di bawah gambar. Dengan kursi dan meja kecil di depan latar polos, foto ini kemungkinan dibuat di studio. Foto orang-orang Afrika Utara semacam ini dibeli pelancong dan kolektor.","Dua pria duduk berhadapan di depan papan berbingkai, dan pria di kanan menjulurkan tangan ke sebuah bidak. Bidak-bidak bundar bertumpuk di papan, jadi kemungkinan backgammon (di sana disebut tawla, antara lain), meski catatan hanya menyebut “permainan papan”. Di meja kecil di depan ada perlengkapan kopi."],"spots":[["Papan dan bidak","Papan berbingkai dengan bidak bundar bertumpuk."],["Penonton yang berdiri","Pria bersabuk kain berdiri di belakang menonton permainan."],["Pria tua di kiri","Pria tua berikat kepala, termenung."],["Pria di kanan","Berkerudung kain putih, membungkuk ke papan."],["Perlengkapan kopi","Baki dan cangkir kecil di meja kecil berukir tembus."],["Tangan yang melangkah","Tangan pemain kanan yang hendak mengambil bidak."]]},"circo":{"title":"Permainan Sirkus (Juego del Circo)","artist":"Manuel Manilla (?)","date":"Tanpa tahun","place":"Meksiko","game":"Permainan taruhan dengan dua dadu","medium":"Cetak timbul (ukiran kayu ujung atau fotogravur) pada kertas cokelat muda","size":"26,2 × 35,0 cm","credit":"","p":["Lembar permainan yang dikaitkan, dengan tanda tanya, pada pembuat cetakan Meksiko Manuel Manilla. Di kanan bawah tertera penjualnya, toko cetakan “El Teatro”, beserta alamatnya. Lembaran murah semacam ini dijual di jalan dan tampaknya dimainkan begitu saja.","Di tengah ada tenda sirkus, dikelilingi penunggang akrobat, menara manusia, orang kuat, dan lainnya, masing-masing bernomor 2 sampai 12. “Penjelasan” di kiri atas menyebut siapa saja, anak-anak juga, boleh bermain: lempar dua dadu lalu taruh taruhan di kotak yang sesuai, atau ambil taruhan yang sudah ada di sana. Siapa yang melempar 12 mengambil semuanya."],"spots":[["Tenda sirkus","Judul “JUEGO DEL CIRCO” dan tenda yang menjadi kotak 12."],["Aturan main","Aturan di bawah judul “ESPLICACION”."],["Penunggang akrobat","Penari di punggung kuda yang berlari: kotak 6."],["Menara manusia","Seorang berdiri di bahu orang lain: kotak 4."],["Orang kuat","Pria mengangkat beban berbentuk meriam: kotak 8."],["Nama toko cetakan","“De venta, Estampería ‘El Teatro’” dan alamatnya."]]},"loteria":{"title":"Kartu Gambar Lotería","artist":"José Guadalupe Posada","date":"1880–1913","place":"Meksiko","game":"Lotería (permainan menyebut gambar)","medium":"Cetak timbul (ukiran kayu ujung atau fotogravur) pada kertas cokelat muda","size":"30,0 × 40,0 cm","credit":"","p":["Pembuat cetakan Meksiko Posada menggambar sangat banyak ilustrasi untuk penerbit Kota Meksiko Antonio Vanegas Arroyo, yang lembaran murahnya memuat berita, lagu, dan permainan. Lembar ini bertuliskan judul “JUEGO DE LOTERIA” dan nama Vanegas Arroyo.","Tiga puluh delapan gambar kecil bernama memenuhi lembar ini: bintang, bulan, kalajengking, setan, tengkorak, ayam jantan, percetakan, dan lainnya. Dalam lotería, mirip bingo, pemanggil menarik kartu dan menyebut gambarnya, lalu pemain menandai gambar itu di papan mereka dengan kacang atau semacamnya. Lembar ini kemungkinan dipotong menjadi kartu."],"spots":[["Judul dan penerbit","“JUEGO DE LOTERIA” dan nama usaha Vanegas Arroyo."],["Bintang","“ESTRELLA”, gambar pertama di kiri atas."],["Bulan","“LUNA”, bulan sabit berwajah."],["Maut","“MUERTE”: kerangka bersabit yang meniup suling."],["Tlachiquero","“TLACHIQUERO”: pria pengumpul getah agave."],["Percetakan","“IMPRENTA”: pekerja di mesin cetak, tempat lembaran seperti ini dibuat."]]},"jeupol":{"title":"“Jeu polonais”, atau Papan Dam","artist":"Anonim","date":"1833–1900","place":"Belgia atau Belanda","game":"Dam (papan 10 × 10)","medium":"Cetak kayu dengan teks cetak timah","size":"32,2 × 39,6 cm","credit":"","p":["Selembar cetakan berjudul bahasa Prancis dan Belanda, “JEU POLONAIS OF DAMSPEL”. “Jeu polonais” (permainan Polandia) adalah nama Prancis untuk dam di papan 10 × 10. Di kanan atas ada nomor seri penerbit, “n. 106”.","Seperti catatan museum, ada 100 kotak, 50 putih dan 50 hitam, dengan bingkai hias di kiri dan kanan. Bidaknya tidak dicetak, jadi kemungkinan ini papan murah yang dimainkan begitu saja dengan kacang atau kancing. Bekas lipatan masih terlihat di kertas."],"spots":[["Judul","Tulisan “JEU POLONAIS OF DAMSPEL”."],["Nomor seri","Nomor penerbit “n. 106”."],["Bingkai kiri","Deretan motif bunga bundar."],["Bingkai kanan","Motif yang sama di sisi lain."],["Seratus kotak","Papan 10 × 10; kotak gelap diarsir garis halus."],["Lipatan","Bekas lipatan di kertas; mungkin dibawa dalam keadaan terlipat."]]},"dkaart":{"title":"Domino dan Kartu untuk Digunting","artist":"Anonim (Brepols)","date":"1800–1833","place":"Belgia (Turnhout)","game":"Domino dan kartu","medium":"Cetak kayu diwarnai biru, merah, dan kuning; teks cetak timah","size":"34,3 × 41,9 cm","credit":"","p":["Menurut catatan museum, lembar ini memuat 32 kartu remi dan 28 batu domino untuk digunting. Ini nomor 114 dalam daftar penerbit Brepols, dengan nama pengecer “D. Pouwels, Bergen-op-Zoom” di bawah. Judulnya dalam bahasa Belanda dan Prancis.","Di kiri, 28 batu dari kosong-kosong sampai enam-enam tersusun segitiga. Di kanan ada 32 kartu, tujuh sampai sepuluh ditambah kartu bergambar dan as tiap jenis: satu set untuk permainan seperti piket. Karena tak pernah digunting, kita melihatnya seperti saat keluar dari mesin cetak."],"spots":[["Judul","Tulisan “DOMINO EN KAARTSPEL”."],["Kosong-kosong","Puncak segitiga: batu tanpa titik."],["Enam-enam","Batu tertinggi, di ujung kanan baris bawah."],["As sekop","Kartu kedua di kolom kiri."],["Kartu bergambar","Raja yang diwarnai merah, biru, dan kuning."],["Pengecer","“D. POUWELS, Bergen-op-Zoom” di bawah."]]},"apen":{"title":"Dua Monyet Bermain Trictrac","artist":"Quirin Boel, menurut David Teniers","date":"1635–1690","place":"Flandria","game":"Trictrac (kerabat backgammon)","medium":"Etsa","size":"11,0 × 14,5 cm","credit":"","p":["Satu lembar dari seri berisi halaman judul dan enam cetakan, tempat monyet memerankan kegiatan manusia. Di kiri bawah tertulis “D. Teniers merancang dan menerbitkan, dengan hak istimewa”: Quirin Boel mengetsa rancangan pelukis Flandria Teniers.","Seperti catatan museum, dua monyet duduk di lantai dengan papan trictrac di antara mereka. Yang kiri minum anggur dari gelas; yang kanan, bertopi bulu ayam jago, menjulurkan tangan ke sebuah bidak. Kemungkinan ini mengejek orang yang larut dalam minuman dan judi."],"spots":[["Papan","Papan trictrac lipat di lantai, dengan segitiga dan bidaknya."],["Monyet kiri","Monyet berjaket yang duduk di depan papan."],["Gelas anggur","Gelas yang diangkat monyet kiri."],["Topi berbulu","Bulu ayam jago di topi monyet kanan."],["Kendi","Kendi di dekat kaki monyet kiri."],["Tulisan","“D Teniers in et excud cum privilegio”."]]},"dstereo":{"title":"Para Pria Bermain Domino di Meja (Foto Stereo)","artist":"Anonim","date":"1850–1880","place":"Tidak diketahui (tulisan bahasa Belanda)","game":"Domino","medium":"Cetak albumen (foto stereo)","size":"8,5 × 17,0 cm","credit":"","p":["Sebuah foto stereo: dua foto yang hampir sama berdampingan. Bila dilihat dengan stereoskop, keduanya menyatu menjadi satu adegan berkedalaman. Di tepi kiri tertulis tangan “Het dominospel” (permainan domino).","Sebuah meja diletakkan di bawah matahari di depan bangunan, dan para pria berkemeja memegang batu domino. Dua orang berdiri menonton; pria di kanan memakai topi putih. Karena semua harus diam, adegan ini kemungkinan diatur untuk kamera."],"spots":[["Batu di meja","Batu domino yang dipegang tertutup."],["Pria bertopi putih","Duduk di kanan dengan batunya."],["Pria berselendang leher","Berdiri menonton dari atas."],["Pria di kiri","Pemuda yang bertopang siku memandangi batunya."],["Tulisan","“Het dominospel.” di tepi kiri."],["Gambar kedua","Foto kanan, diambil dari titik yang sedikit bergeser: berdua tampak tiga dimensi."]]},"gojo":{"title":"Dua Wanita Bermain Go","artist":"Anonim","date":"1870–1891","place":"Jepang","game":"Kemungkinan go","medium":"Cetak albumen diwarnai tangan","size":"9,0 × 13,5 cm","credit":"","p":["Foto hitam-putih yang diwarnai dengan kuas. Foto semacam ini dibuat di studio-studio Yokohama dan tempat lain sebagai cendera mata bagi orang asing. Foto ini dulu ditempel di album perjalanan ke Manila.","Berlatar hiasan ceruk dan sekat lipat, dua wanita duduk berhadapan di depan papan berkaki, dan wanita di kiri sedang meletakkan batu. Ada batu putih dan hitam di papan, jadi kemungkinan go, meski catatan museum menyebut “permainan papan”. Di baki depan ada kue dan mangkuk."],"spots":[["Papan dan batu","Papan tebal berkaki dengan batu putih dan hitam."],["Tangan yang melangkah","Wanita kiri meletakkan batu."],["Wanita di kiri","Menoleh ke arah kita; obinya diikat simpul besar."],["Wanita di kanan","Berkimono belang, tangannya di dekat papan."],["Baki dan mangkuk","Kue dan cangkir di depan."],["Bunga","Vas bunga di atas tatakan di belakang."]]},"meade":{"title":"Dua Pria Bermain Catur","artist":"Charles Richard Meade dan Henry William Mathew Meade","date":"1852","place":"Amerika Serikat","game":"Catur","medium":"Dagerotipe","size":"6,9 × 8,3 cm","credit":"","p":["Sebuah dagerotipe dari studio kakak-beradik Meade, fotografer kelahiran Inggris yang bekerja di Amerika. Dagerotipe membentuk gambar langsung di lempeng tembaga berlapis perak, jadi setiap buahnya unik dan tak bisa dicetak ulang; yang ini disimpan dalam kotak kulit kecil di balik bingkai emas.","Dua pemuda menghadap papan catur di atas meja kecil; yang kiri menyentuh sebuah bidak. Yang kanan, tangan di dada, mengamati papan. Karena harus diam lama, langkah ini kemungkinan hanya pose."],"spots":[["Papan catur","Papan dan bidak putih di atas meja kecil bertaplak bunga."],["Pria di kiri","Jarinya di sebuah bidak."],["Pria di kanan","Menunduk memandangi papan."],["Tangan di dada","Tangan pemain kanan yang sedang berpikir."],["Taplak","Meja kecil bertaplak kain bermotif bunga."],["Bingkai emas","Bingkai dan kotak yang melindungi lempeng."]]},"reise":{"title":"Perjalanan Keliling Dunia, Lewat Air dan Darat","artist":"Anonim","date":"Abad ke-19","place":"Kemungkinan wilayah berbahasa Jerman","game":"Permainan balap satu dadu dengan taruhan","medium":"Litografi","size":"42,5 × 33,7 cm","credit":"","p":["Lembar permainan berjudul bahasa Jerman “Perjalanan keliling dunia, lewat air dan darat: permainan dadu yang baru dan menghibur”. Papan bundar berisi kotak 1 sampai 41, dengan gambar balon udara, kapal layar, kapal uap, lokomotif, orang dari berbagai bangsa, dan lainnya. Di kanan bawah ada nomor “No. 107”.","Di bawahnya tercetak aturan dalam bahasa Jerman, Inggris, Belanda, dan Prancis. Setiap pemain membayar dulu 15 mark ke “kantong perjalanan” bersama, lalu bergiliran melempar satu dadu dan memajukan tandanya. Berhenti di gambar besar menang 2 mark, nomor tanpa gambar didenda 2 mark, dan yang mencapai 41 mengambil semua sisanya."],"spots":[["41: kereta pos","Tujuan di tengah: kereta kuda dengan penumpang dan kusir."],["1: orang Inggris","Kotak awal, “Engländer” bertopi tinggi."],["Balon udara","Kotak dengan balon di langit."],["Kapal layar","Kapal dengan layar terkembang."],["Lokomotif","Lokomotif uap yang mengepulkan asap."],["Aturan","Aturan yang dicetak dalam empat bahasa."]]},"huchten":{"title":"Dadu Penentu Hidup atau Mati","artist":"Jan van Huchtenburg","date":"1680–1720","place":"Belanda","game":"Dadu","medium":"Cat minyak di atas kanvas","size":"67,5 × 76,0 cm","credit":"","p":["Karya pelukis Belanda Jan van Huchtenburg (1647–1733), yang dikenal dengan lukisan pertempuran, bertanda tangan di kiri bawah. Judul museumnya “Permainan dadu untuk nyawa”. Di luar sebuah benteng, dua tahanan melempar dadu di atas genderang, dikelilingi perwira dan prajurit.","Di kanan belakang berdiri tiang gantungan, dan dari tembok benteng di kiri para prajurit menonton. Kemungkinan ini prajurit terhukum yang mengundi dengan dadu siapa yang akan dieksekusi. Seorang tahanan menunjuk genderang; yang lain berlutut memandangi lemparan."],"spots":[["Genderang dan dadu","Genderang menjadi meja tempat dadu dilempar."],["Tahanan yang menunjuk","Berdiri sambil menunjuk genderang."],["Tahanan yang berlutut","Berkemeja putih, membungkuk di atas genderang."],["Perwira berkuda","Bertopi, memandang dari atas kuda."],["Tiang gantungan","Tiang gantungan di kanan atas."],["Prajurit di tembok","Prajurit yang menonton dari tembok benteng."]]},"vertu":{"title":"Permainan Kebajikan (Spel der Deugd)","artist":"Jan Gerritsz. Visser (rancangan J. Voorman)","date":"1798","place":"Belanda","game":"Permainan taruhan dengan dua dadu","medium":"Gravir, etsa, dan cetak timah","size":"56,9 × 38,0 cm","credit":"","p":["Lembar permainan besar berjudul bahasa Belanda dan Prancis “Permainan Kebajikan”. Di tengah kuil bertiang duduk Kebajikan, dengan Kemakmuran berdiri di kiri dan Kemiskinan di kanan. Di tiang-tiang tergantung medali kebajikan seperti Ketulusan, Rasa Syukur, dan Cinta, sedangkan di alasnya ada sifat buruk seperti Kekikiran, Kesombongan, dan Kemalasan.","Menurut aturan di bawah, permainan ini memakai dua dadu atau undian. Dengan dadu, para pemain bertaruh total 63, lalu melempar bergiliran mengikuti arah matahari. Tiap lemparan menyebut satu kebajikan atau keburukan: dobel enam, Kebajikan, mengambil seluruh taruhan, dan dobel satu, Keburukan, membayar delapan. Di bawah tiap gambar, “T” berarti ambil dan “B” berarti bayar."],"spots":[["Judul","“SPEL DER DEUGD” di bidang segitiga atap."],["Kebajikan","Kebajikan bertakhta di tengah; dobel enam mengambil semuanya."],["Kemakmuran","Kemakmuran dengan tanduk kelimpahan."],["Keburukan","Dobel satu, Keburukan: anak yang mengangkat cawan."],["Kekikiran","Kekikiran di alas; “B” dan dadu menunjukkan bayarannya."],["Aturan","Aturan yang tercetak rapat di bawah."]]},"charros":{"title":"Para Charro Penyelundup: Permainan Dadu","artist":"José Guadalupe Posada","date":"Tanpa tahun","place":"Meksiko","game":"Permainan balap dengan tiga dadu","medium":"Litografi","size":"29,9 × 40,4 cm","credit":"","p":["Permainan balap bergambar karya Posada, berjudul “LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS” (Para charro penyelundup / Permainan dadu). Di bawah tertera percetakan A. Vanegas Arroyo, Meksiko, dan Posada menandatanganinya di kanan bawah. Charro, penunggang kuda Meksiko, berpacu bersombrero di sudut-sudutnya.","Kotak-kotak bundar berbingkai tali berkelok di seluruh papan, berisi hewan, orang, kereta api, dan lainnya. “Penjelasan” di kanan atas menyebut tiga dadu. Tiga angka satu pada lemparan pertama menang; jatuh di tengkorak kalah; di rusa mengambil dari kas, di perampok membayar, dan di singa diam sampai ada pemain lain datang."],"spots":[["Judul","“LOS CHARROS CONTRABANDISTAS / JUEGO DE DADOS”."],["Penjelasan","Aturan di bawah judul “EXPLICACION”."],["Para pemain","Orang-orang di sekitar meja bermain papan, kiri bawah."],["Dadu","Tiga dadu di tengah papan."],["Charro berkuda","Charro berpacu sambil memutar laso."],["Percetakan","“IMPRENTA DE A. VANEGAS ARROYO, MÉXICO”."]]},"snuffwq":{"title":"Botol Tembakau Sedot dengan Pemain Weiqi","artist":"Tiongkok","date":"Dinasti Qing, tanda dan masa pemerintahan Daoguang (1820–50)","place":"Tiongkok","game":"Weiqi (go)","medium":"Porselen dilukis email di atas glasir","size":"Tinggi 5,7 cm","credit":"","p":["Botol kecil untuk membawa tembakau sedot di Tiongkok masa Qing. Menurut catatan museum, botol ini bertanda masa pemerintahan Daoguang dan berasal dari 1820–50. Pada badannya yang berupa porselen putih setinggi sekitar enam sentimeter dilukis pemandangan gunung dan sosok manusia.","Di dekat batu seperti gua, dua orang tua duduk berhadapan di depan papan weiqi di atas meja biru; yang kiri hendak meletakkan batu. Di belakangnya seorang anak memegang tongkat menonton. Tema ini kemungkinan mengingatkan pada kisah penebang kayu yang menonton para dewa bermain."],"spots":[["Papan","Papan di atas meja biru dengan kisi halus."],["Orang tua berjanggut","Berjubah ungu, menjulurkan tangan ke papan."],["Orang tua di seberang","Duduk di kanan, mengangkat tangan."],["Anak bertongkat","Menonton dari belakang."],["Gua batu","Batu seperti gua di belakang."],["Tutup","Tutup berwarna hijau."]]}};
